<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_path}js/area_pcap.js?13"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Platform/manage')}">平台分类列表</a>|					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Platform/add')}','添加分类',800,560,true,false,false,addbtn,'add',true);">添加分类</a>					<a href="{pigcms{:U('Platform/activity_list')}" class="on">平台活动列表</a>|					<a href="{pigcms{:U('Platform/checkList')}">分类管理员审核列表</a>|					<a href="{pigcms{:U('Platform/examine_refundList')}">退款审核列表</a>|					<a href="{pigcms{:U('Platform/platform_config')}">配置项</a>|				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td style="width:60%;">						<form action="{pigcms{:U('Platform/activity_list')}" method="get">							<input type="hidden" name="c" value="Platform"/>							<input type="hidden" name="a" value="activity_list"/>							筛选: 							<if condition="$admin_area neq 3">							<div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}"  style="display:inline"></div>							</if>							<input type="submit" value="查询" class="button"/>													</form>					</td>									</tr>			</table>							<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup><col> <col> <col width="140"> <col><col><col><col><col><col width="80" align="center"><col><col><col><col> </colgroup>						<thead>							<tr>								<th>编号</th>								<th>活动主题</th>								<th>活动详情</th>								<th>创建人</th>								<th>联系方式</th>								<th>所属区域</th>								<th>分类名称</th>								<th>状态</th>								<th>审核状态</th>								<th>是否置顶</th>								<th>添加时间</th>								<th>报名详情</th>								<th>评价详情</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.activity_id}</td>										<td>{pigcms{$vo.title}</td>										<td>{pigcms{$vo.desc}</td>										<td>{pigcms{$vo.nickname}</td>										<td>                                            <if condition="$vo.phone gt 0">                                                <p>联系手机号：<b>{pigcms{$vo.phone}</b></p>                                            </if>                                            <if condition="$vo.login_phone gt 0">                                                <p>注册手机号：<b>{pigcms{$vo.login_phone}</b></p>                                            </if>                                        </td>										<td>{pigcms{$vo.provincename}{pigcms{$vo.cityname}</td>										<td>{pigcms{$vo.cate_name}</td>										<td>											<if condition="$vo['status'] eq 1">													<font style="color:green;">进行中</font>											<elseif condition="$vo['status'] eq 2"/>														<font style="color:red;">已取消</font>												<else />													已结束											</if>											</td>										<td>											<if condition="$vo['examine_status'] eq 1">													<font style="color:#CD8500;">待审核</font>											<elseif condition="$vo['examine_status'] eq 2"/>													<font style="color:green;">已通过</font>												<else />													<font style="color:red;">已拒绝</font>											</if>											</td>										<td>											<if condition="$vo['is_top'] eq 0">												未置顶											<else/>												<font style="color:red;">已置顶</font>												</if>											</td>										<td><if condition="$vo['add_time']">{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}<else/>无</if></td>										<td>											<a href="{pigcms{:U('Platform/activity_join',array('activity_id'=>$vo['activity_id']))}">查看</a>										</td>										<td>											<a href="{pigcms{:U('Platform/activity_reply',array('activity_id'=>$vo['activity_id']))}">查看</a>										</td>											<!-- <td>											<span class="cb-enable"><label class="cb-enable <if condition="$vo['status'] eq 0">selected</if>"><span onclick="discoverSwitch('{pigcms{$vo.id}', 0)" >开启</span><input type="radio" value="0" <if condition="$vo['status'] eq 0">checked="checked"</if> /></label></span>                                            <span class="cb-disable"><label class="cb-disable <if condition="$vo['status'] eq 1">selected</if>"><span onclick="discoverSwitch('{pigcms{$vo.id}', 1)">关闭</span><input type="radio" value="1" <if condition="$vo['status'] eq 1">checked="checked"</if> /></label></span>										</td> -->										<td>										<a href="javascript:void(0);" class="delete_row" parameter="activity_id={pigcms{$vo.activity_id}" url="{pigcms{:U('Platform/del_activity')}">删除</a>										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>				</div><script>   var url = "{pigcms{$config.site_url}"    var export_url = "{pigcms{:U('Merchant/export_info')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><script>            var lockInfo = false;            function discoverSwitch(id, status) {            	console.log(id);                if (lockInfo) return;                lockInfo = true;                var url = '';                var close_category = "{pigcms{:U('Platform/close_cate')}";                var open_category = "{pigcms{:U('Platform/open_cate')}";                if (0 == status) {                    url = open_category;                } else if(1 == status) {                    url = close_category;                } else {                    return;                }                $.post(url,{'id': id},function(data){                    console.log(data)                    if (data && (data.status === 1 || data.status === '1')) {                        location.reload();                    } else {                        alert(data.info)                    }                },'json')                setTimeout(function(){                    lockInfo = false;                },1000);            }        </script><include file="Public:footer"/>